    @Test
    fun everyNumberedRuleRejects() {
        cases.forEach { case ->
            val result = SnoParser.parse(case.json)
            assertTrue(result is SnoResult.Invalid, "rule ${case.rule} should have been refused: ${case.json}")
            assertEquals(case.rule, result.rule, "wrong rule blamed for ${case.json} (said: ${result.reason})")
        }
    }

    @Test
    fun theTableCoversEveryRule() {
        assertEquals(
            setOf("1", "2", "3", "4", "5", "6", "7", "8", "8a", "8b", "8c", "10"),
            cases.map { it.rule }.toSet(),
        )
        assertEquals(25, cases.size)
    }

    @Test
    fun contentThatIsNotAJsonObjectIsRefused() {
        listOf("", "not json", "[]", "null", "12").forEach {
            assertTrue(SnoParser.parse(it) is SnoResult.Invalid, "should have been refused: $it")
        }
    }
}
